def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    ans = n + 1
    last = {}

    for i in range(n):
        x = int(data[i + 1])
        if x in last:
            length = i - last[x] + 1
            if length < ans:
                ans = length
                if ans == 2:
                    break
        last[x] = i

    print(-1 if ans == n + 1 else ans)

if __name__ == "__main__":
