from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        freq = {}
        n = len(nums)

        for i in range(n - k + 1):
            for value in set(nums[i:i + k]):
                freq[value] = freq.get(value, 0) + 1

        for value in sorted(freq, reverse=True):
            if freq[value] == 1:
                return value

        return -1
