        s_parts = [s[i:j] for i in range(n + 1) for j in range(i, n + 1)]
        t_parts = [t[i:j] for i in range(m + 1) for j in range(i, m + 1)]

        ans = 0

        for a in s_parts:
            len_a = len(a)
            for b in t_parts:
                length = len_a + len(b)
                if length <= ans:
