def magic_square_test(matrix):
    """
    Return True if the given matrix is a magic square,
    meaning all rows, columns, and both main diagonals
    have the same sum.
    """
    if not matrix:
        return False

    n = len(matrix)

    try:
        if any(len(row) != n for row in matrix):
            return False

        magic_sum = sum(matrix[0])

        for row in matrix:
            if sum(row) != magic_sum:
                return False

        for col in range(n):
            if sum(matrix[row][col] for row in range(n)) != magic_sum:
                return False

        if sum(matrix[i][i] for i in range(n)) != magic_sum:
            return False

        if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
            return False

    except TypeError:
        return False

    return True


