def minPath(grid, k):
    if k <= 0 or not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])

    r = c = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    path = [1]

    for _ in range(1, k):
        best_val = None
        best_r, best_c = r, c

        if r > 0:
            val = grid[r - 1][c]
            if best_val is None or val < best_val:
                best_val = val
                best_r, best_c = r - 1, c

        if r + 1 < rows:
            val = grid[r + 1][c]
            if best_val is None or val < best_val:
                best_val = val
                best_r, best_c = r + 1, c

        if c > 0:
            val = grid[r][c - 1]
            if best_val is None or val < best_val:
                best_val = val
                best_r, best_c = r, c - 1

        if c + 1 < cols:
            val = grid[r][c + 1]
            if best_val is None or val < best_val:
                best_val = val
                best_r, best_c = r, c + 1

        if best_val is None:
            break

        path.append(best_val)
        r, c = best_r, best_c

    return path
