from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers
        offline_until = [0] * numberOfUsers

        sorted_events = sorted(events, key=lambda e: int(e[1]))
        i = 0
        n = len(sorted_events)

        while i < n:
            t = int(sorted_events[i][1])

            # Users whose offline period has ended at this timestamp become online.
            for user in range(numberOfUsers):
                if not online[user] and offline_until[user] <= t:
                    online[user] = True

            messages = []

            # Process all OFFLINE events at this timestamp before MESSAGE events.
            while i < n and int(sorted_events[i][1]) == t:
                event = sorted_events[i]

                if event[0] == "OFFLINE":
                    user_id = int(event[2])
                    if online[user_id]:
                        online[user_id] = False
                        offline_until[user_id] = t + 60
                else:
                    messages.append(event[2])

                i += 1

            # Process all MESSAGE events at this timestamp.
            for mentions_string in messages:
                for token in mentions_string.split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if online[user]:
                                mentions[user] += 1
                    else:
                        user_id = int(token[2:])
                        if 0 <= user_id < numberOfUsers:
                            mentions[user_id] += 1

        return mentions
