class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        ans = total_k

        for target in set(nums):
            if target == k:
                continue

            cur = 0
            best = 0

            for v in nums:
                if v == target:
                    cur += 1
                elif v == k:
                    cur -= 1

                if cur < 0:
                    cur = 0
                elif cur > best:
                    best = cur

            ans = max(ans, total_k + best)

        return ans
